<script setup>
import { computed, ref } from 'vue';
import { Head, Link, usePage, useForm } from '@inertiajs/vue3';
import AcademyLayout from '@/Layouts/AcademyLayout.vue';
import Icon from '@/Components/AcademyIcon.vue';
const props = defineProps({ stats: Object, modules: Array, resume: Object, recent: Array, bookmarks: Array, attempts: Array, goal: Object });
const firstName = computed(() => usePage().props.auth.user.name.split(' ')[0]);
const editingGoal = ref(false);
const goalForm = useForm({ daily_lessons: props.goal.daily_lessons, weekly_lessons: props.goal.weekly_lessons });
const cards = computed(() => [
{ label: 'Learning modules', value: String(props.stats.modules).padStart(2, '0'), icon: 'layers', note: 'One connected learning path', tone: 'purple' },
{ label: 'Lessons completed', value: String(props.stats.completed).padStart(2, '0'), icon: 'check', note: 'of ' + props.stats.lessons + ' available lessons', tone: 'green' },
{ label: 'Currently exploring', value: String(props.stats.in_progress).padStart(2, '0'), icon: 'code', note: 'Lessons in progress', tone: 'orange' },
{ label: 'Overall progress', value: props.stats.percentage + '%', icon: 'gauge', note: 'Every lesson moves you forward', tone: 'blue' },
]);
function saveGoal() { goalForm.put(route('goals.update'), { preserveScroll: true, onSuccess: () => editingGoal.value = false }); }
</script>
<template>
    <Head title="Your learning workspace" />
    <AcademyLayout title="Overview">
        <div class="page-heading"><div><span class="eyebrow"><span class="tiny-line" /> YOUR LEARNING, IN FOCUS</span><h1>Keep building, {{ firstName }}<span class="heading-dot">.</span></h1><p>A little more knowledge. A lot more possibility. Let’s make progress.</p></div><Link :href="route('lessons.index')" class="button secondary">Explore lessons <Icon name="arrow" size="17" /></Link></div>
        <div class="stats-grid"><article v-for="card in cards" :key="card.label" class="stat-card panel"><div><span>{{ card.label }}</span><span :class="['stat-icon', card.tone]"><Icon :name="card.icon" size="18" /></span></div><strong>{{ card.value }}</strong><small>{{ card.note }}</small></article></div>
        <div class="dashboard-columns">
            <div class="dashboard-primary">
                <section v-if="resume" class="continue-card"><div class="continue-copy"><span class="continue-label"><span class="pulse-dot" /> YOUR NEXT CHAPTER</span><h2>Good code starts with<br />a deeper understanding.</h2><p>{{ resume.title }}</p><div class="continue-meta"><span>{{ resume.module.title }}</span><span>·</span><Icon name="clock" size="14" /><span>{{ resume.estimated_minutes }} min</span></div><Link :href="route('lessons.show', resume.slug)" class="button light">Continue learning <Icon name="arrow" size="17" /></Link></div><div class="code-illustration" aria-hidden="true"><div class="mini-editor"><div class="mini-editor-top"><i /><i /><i /><span>your-next-level.php</span></div><div class="mini-editor-body"><span class="line-number">01</span><span class="code-purple">class</span> <span class="code-yellow">BetterDeveloper</span><br /><span class="line-number">02</span>{<br /><span class="line-number">03</span>&nbsp;&nbsp;<span class="code-purple">public function</span> grow()<br /><span class="line-number">04</span>&nbsp;&nbsp;{<br /><span class="line-number">05</span>&nbsp;&nbsp;&nbsp;&nbsp;<span class="code-pink">$this</span>->learn();<br /><span class="line-number">06</span>&nbsp;&nbsp;&nbsp;&nbsp;<span class="code-pink">$this</span>->build();<br /><span class="line-number">07</span>&nbsp;&nbsp;}<br /><span class="line-number">08</span>}</div></div><span class="floating-code-badge"><Icon name="code" size="21" /></span></div></section>
                <section v-else class="continue-card"><div class="continue-copy"><span class="continue-label">KEEP YOUR CURIOSITY</span><h2>{{ stats.lessons ? 'You’ve completed the path.' : 'Your learning path is on its way.' }}</h2><p>{{ stats.lessons ? 'Revisit the library and turn understanding into practice.' : 'Published lessons will appear here when they are ready.' }}</p><Link :href="route('lessons.index')" class="button light">Open library <Icon name="arrow" size="17" /></Link></div></section>
                <section class="learning-path-section"><div class="section-heading"><div><h2>Your learning path</h2><p>A clear route from fundamentals to real-world confidence.</p></div><span class="subtle-label">{{ modules.length }} modules</span></div><div class="module-list"><Link v-for="(module, index) in modules" :key="module.id" :href="route('lessons.index', { module: module.id })" class="module-row"><span class="module-index">{{ String(index + 1).padStart(2, '0') }}</span><span :class="['module-icon', ['purple', 'orange', 'blue', 'green'][index % 4]]"><Icon :name="module.icon" size="22" /></span><div class="module-info"><h3>{{ module.title }}</h3><p>{{ module.lessons_count }} lessons <span>·</span> <span class="capitalize">{{ module.difficulty }}</span></p></div><div class="module-progress"><span>{{ module.completed_count }} / {{ module.lessons_count }}</span><div class="progress-track"><span :style="{ width: (module.lessons_count ? module.completed_count / module.lessons_count * 100 : 0) + '%' }" /></div></div><Icon name="chevron" size="16" /></Link></div></section>
                <section class="panel recent-panel"><div class="section-heading"><h2>Recently explored</h2><Link :href="route('history')" class="text-link">View history <Icon name="arrow" size="15" /></Link></div><div v-if="!recent.length" class="empty-inline"><Icon name="book" /><p>Your recent lessons will appear here. Start with PHP fundamentals.</p></div><Link v-for="item in recent" :key="item.id" :href="route('lessons.show', item.lesson.slug)" class="recent-row"><span class="module-icon"><Icon :name="item.lesson.module.icon" size="18" /></span><span><strong>{{ item.lesson.title }}</strong><small>{{ item.lesson.module.title }}</small></span><span :class="['status-tag', { done: item.completed_at }]">{{ item.completed_at ? 'Completed' : 'In progress' }}</span><Icon name="arrow" size="16" /></Link></section>
            </div>
            <div class="dashboard-secondary">
                <section class="goal-card panel"><div class="section-heading"><h2>Aim for consistency</h2><Icon name="target" size="19" /></div><p>Your daily learning goal</p><div class="goal-ring" :style="{ '--goal-progress': Math.min(stats.today / goal.daily_lessons, 1) * 360 + 'deg' }"><div><strong>{{ stats.today }}<small>/{{ goal.daily_lessons }}</small></strong><span>lessons today</span></div></div><div class="goal-status"><span class="tiny-dot" />{{ stats.today >= goal.daily_lessons ? 'Daily goal reached. Nice work!' : 'A small step makes a difference.' }}</div><div class="weekly-goal"><span>This week</span><strong>{{ stats.this_week }} / {{ goal.weekly_lessons }} lessons</strong></div><div class="progress-track"><span :style="{ width: Math.min(stats.this_week / goal.weekly_lessons * 100, 100) + '%' }" /></div><button class="goal-edit" @click="editingGoal = !editingGoal">{{ editingGoal ? 'Cancel' : 'Adjust learning goals' }} <span>↗</span></button><form v-if="editingGoal" class="goal-form" @submit.prevent="saveGoal"><label>Daily lessons<input v-model="goalForm.daily_lessons" type="number" min="1" max="20" required /></label><label>Weekly lessons<input v-model="goalForm.weekly_lessons" type="number" min="1" max="100" required /></label><p v-for="error in goalForm.errors" :key="error" class="error-text">{{ error }}</p><button class="button primary" :disabled="goalForm.processing">Save goals</button></form></section>
                <section class="panel bookmarks-panel"><div class="section-heading"><h2>Saved for later</h2><Icon name="bookmark" size="18" /></div><div v-if="!bookmarks.length" class="empty-inline muted"><p>A good idea deserves a bookmark. Save lessons as you explore.</p></div><Link v-for="bookmark in bookmarks" :key="bookmark.id" :href="route('lessons.show', bookmark.lesson.slug)" class="saved-lesson"><span class="tiny-dot" /><span><strong>{{ bookmark.lesson.title }}</strong><small>{{ bookmark.lesson.module.title }}</small></span><Icon name="chevron" size="14" /></Link><Link :href="route('lessons.index', { bookmarked: 1 })" class="panel-bottom-link">All bookmarks <Icon name="arrow" size="15" /></Link></section>
                <section class="quiz-score-card panel"><span class="stat-icon orange"><Icon name="trophy" size="20" /></span><h3>Knowledge into confidence.</h3><p>{{ attempts.length ? 'Your average across all quiz attempts' : 'Test what you know with a quiz at the end of each lesson.' }}</p><strong v-if="attempts.length" class="quiz-average">{{ stats.average_score }}<small>% average</small></strong><Link :href="route(attempts.length ? 'history' : 'lessons.index')" class="text-link">{{ attempts.length ? 'Review your scores' : 'Find your next challenge' }} <Icon name="arrow" size="15" /></Link></section>
                <div class="workspace-footnote"><Icon name="shield" size="15" /><span>Your progress is saved automatically.<br />Learn at your own pace.</span></div>
            </div>
        </div>
    </AcademyLayout>
</template>
